<?php
$baseParams = array_filter($filters, static fn($value, $key) => !in_array($key, ['sort', 'direction'], true) && $value !== '', ARRAY_FILTER_USE_BOTH);
$sortUrl = static function (string $column) use ($baseParams, $filters): string {
    $direction = ($filters['sort'] ?? '') === $column && ($filters['direction'] ?? 'desc') === 'asc' ? 'desc' : 'asc';
    return ROOT . '/client-orders/archive?' . http_build_query(array_merge($baseParams, ['sort' => $column, 'direction' => $direction]));
};
$sortIcon = static function (string $column) use ($filters): string {
    if (($filters['sort'] ?? '') !== $column) return 'bi-arrow-down-up text-muted';
    return ($filters['direction'] ?? 'desc') === 'asc' ? 'bi-sort-up' : 'bi-sort-down';
};
?>
<div class="page-heading">
