    <section class="section"><div class="card">
        <div class="card-header d-flex flex-wrap align-items-center gap-2 justify-content-between"><h4 class="card-title mb-0"><i class="bi bi-archive me-2 text-primary"></i>Archiwalne zamówienia</h4><a href="<?= ROOT ?>/client-orders" class="btn btn-outline-secondary btn-sm"><i class="bi bi-arrow-left me-1"></i>Bieżące zamówienia</a></div>
