            <div class="col-6 col-md-2"><label class="form-label small" for="date_from">Wysyłka od</label><input class="form-control" id="date_from" type="date" name="date_from" value="<?= htmlspecialchars($filters['date_from']) ?>"></div><div class="col-6 col-md-2"><label class="form-label small" for="date_to">Wysyłka do</label><input class="form-control" id="date_to" type="date" name="date_to" value="<?= htmlspecialchars($filters['date_to']) ?>"></div>
            <div class="col-12 col-md-2"><label class="form-label small" for="document">Dokument</label><select class="form-select" id="document" name="document"><option value="">Wszystkie</option><option value="proforma" <?= $filters['document'] === 'proforma' ? 'selected' : '' ?>>Z proformą</option><option value="wdt" <?= $filters['document'] === 'wdt' ? 'selected' : '' ?>>Z WDT</option><option value="none" <?= $filters['document'] === 'none' ? 'selected' : '' ?>>Bez dokumentu</option></select></div><div class="col-12 col-md-2 d-flex gap-2"><button class="btn btn-primary" type="submit"><i class="bi bi-funnel me-1"></i>Filtruj</button><a class="btn btn-light" href="<?= ROOT ?>/client-orders/archive">Wyczyść</a></div>
