            <?php foreach ($group['orders'] as $order): ?><tr class="collapse show <?= $collapseId ?>"><td class="ps-3 fw-semibold"><?= htmlspecialchars($order['company']) ?></td><td><div><?= htmlspecialchars($order['order_description'] ?? '') ?></div><?php if (!empty($order['reference'])): ?><small class="text-muted">Ref.: <?= htmlspecialchars($order['reference']) ?></small><?php endif; ?></td><td class="text-nowrap small"><?= htmlspecialchars($order['create_date']) ?><br><?= htmlspecialchars($order['create_order_time']) ?></td><td class="text-nowrap"><i class="bi bi-truck me-1 text-primary"></i><?= htmlspecialchars($order['expected_shipping_date']) ?></td><td class="text-end text-nowrap"><?= $order['total_sum_kg'] ?? 0 ?> kg</td><td><span class="badge <?= (int) $order['status'] === 2 ? 'bg-success' : ((int) $order['status'] === 5 ? 'bg-secondary' : 'bg-info text-dark') ?>"><?= htmlspecialchars($order['status_name']) ?></span></td><td class="text-center pe-3"><?php if (!empty($order['id_proforma'])): ?><a class="btn btn-outline-info btn-sm" target="_blank" href="<?= ROOT ?>/ajax/proforma-documents/<?= (int) $order['id_proforma'] ?>/document"><i class="bi bi-file-earmark-text me-1"></i>Proforma</a><?php else: ?><span class="text-muted small">Brak proformy</span><?php endif; ?></td></tr><?php endforeach; ?>
